  1→import * as http from 'node:http'
  2→import * as fs from 'node:fs'
  3→import * as path from 'node:path'
  4→import * as os from 'node:os'
  5→import * as crypto from 'node:crypto'
  6→import { fileURLToPath } from 'node:url'
  7→import type { OpenACPCore } from './core.js'
  8→import type { TopicManager } from './topic-manager.js'
  9→import { createChildLogger } from './log.js'
 10→import { getAgentCapabilities } from './agent-registry.js'
 11→
 12→const log = createChildLogger({ module: 'api-server' })
 13→
 14→const DEFAULT_PORT_FILE = path.join(os.homedir(), '.openacp', 'api.port')
 15→
 16→let cachedVersion: string | undefined
 17→
 18→function getVersion(): string {
 19→  if (cachedVersion) return cachedVersion
 20→  try {
 21→    const __filename = fileURLToPath(import.meta.url)
 22→    const pkgPath = path.resolve(path.dirname(__filename), '../../package.json')
 23→    const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf-8'))
 24→    cachedVersion = pkg.version ?? '0.0.0-dev'
 25→  } catch {
 26→    cachedVersion = '0.0.0-dev'
 27→  }
 28→  return cachedVersion!
 29→}
 30→
 31→const SENSITIVE_KEYS = ['botToken', 'token', 'apiKey', 'secret', 'password', 'webhookSecret']
 32→
 33→function redactConfig(config: unknown): unknown {
 34→  const redacted = structuredClone(config)
 35→  redactDeep(redacted as Record<string, unknown>)
 36→  return redacted
 37→}
 38→
 39→function redactDeep(obj: Record<string, unknown>): void {
 40→  for (const [key, value] of Object.entries(obj)) {
 41→    if (SENSITIVE_KEYS.includes(key) && typeof value === 'string') {
 42→      obj[key] = '***'
 43→    } else if (value && typeof value === 'object' && !Array.isArray(value)) {
 44→      redactDeep(value as Record<string, unknown>)
 45→    }
 46→  }
 47→}
 48→
 49→export interface ApiConfig {
 50→  port: number
 51→  host: string
 52→}
 53→
 54→export class ApiServer {
 55→  private server: http.Server | null = null
 56→  private actualPort: number = 0
 57→  private portFilePath: string
 58→  private startedAt = Date.now()
 59→  private secret: string = ''
 60→  private secretFilePath: string
 61→
 62→  constructor(
 63→    private core: OpenACPCore,
 64→    private config: ApiConfig,
 65→    portFilePath?: string,
 66→    private topicManager?: TopicManager,
 67→    secretFilePath?: string,
 68→  ) {
 69→    this.portFilePath = portFilePath ?? DEFAULT_PORT_FILE
 70→    this.secretFilePath = secretFilePath ?? path.join(os.homedir(), '.openacp', 'api-secret')
 71→  }
 72→
 73→  async start(): Promise<void> {
 74→    this.loadOrCreateSecret()
 75→    this.server = http.createServer((req, res) => this.handleRequest(req, res))
 76→
 77→    await new Promise<void>((resolve, reject) => {
 78→      this.server!.on('error', (err: NodeJS.ErrnoException) => {
 79→        if (err.code === 'EADDRINUSE') {
 80→          log.warn({ port: this.config.port }, 'API port in use, continuing without API server')
 81→          this.server = null
 82→          // actualPort stays 0, port file not written
 83→          resolve()
 84→        } else {
 85→          reject(err)
 86→        }
 87→      })
 88→
 89→      this.server!.listen(this.config.port, this.config.host, () => {
 90→        const addr = this.server!.address()
 91→        if (addr && typeof addr === 'object') {
 92→          this.actualPort = addr.port
 93→        }
 94→        this.writePortFile()
 95→        log.info({ host: this.config.host, port: this.actualPort }, 'API server listening')
 96→        resolve()
 97→      })
 98→    })
 99→  }
100→
101→  async stop(): Promise<void> {
102→    this.removePortFile()
103→    if (this.server) {
104→      await new Promise<void>((resolve) => {
105→        this.server!.close(() => resolve())
106→      })
107→      this.server = null
108→    }
109→  }
110→
111→  getPort(): number {
112→    return this.actualPort
113→  }
114→
115→  private writePortFile(): void {
116→    const dir = path.dirname(this.portFilePath)
117→    fs.mkdirSync(dir, { recursive: true })
118→    fs.writeFileSync(this.portFilePath, String(this.actualPort))
119→  }
120→
121→  private removePortFile(): void {
122→    try { fs.unlinkSync(this.portFilePath) } catch { /* ignore */ }
123→  }
124→
125→  private loadOrCreateSecret(): void {
126→    const dir = path.dirname(this.secretFilePath)
127→    fs.mkdirSync(dir, { recursive: true })
128→
129→    try {
130→      this.secret = fs.readFileSync(this.secretFilePath, 'utf-8').trim()
131→      if (this.secret) {
132→        // Warn if file permissions are too open (like SSH does for private keys)
133→        try {
134→          const stat = fs.statSync(this.secretFilePath)
135→          const mode = stat.mode & 0o777
136→          if (mode & 0o077) {
137→            log.warn({ path: this.secretFilePath, mode: '0' + mode.toString(8) }, 'API secret file has insecure permissions (should be 0600). Run: chmod 600 %s', this.secretFilePath)
138→          }
139→        } catch { /* stat failed, skip check */ }
140→        return
141→      }
142→    } catch {
143→      // File doesn't exist, create it
144→    }
145→
146→    this.secret = crypto.randomBytes(32).toString('hex')
147→    fs.writeFileSync(this.secretFilePath, this.secret, { mode: 0o600 })
148→  }
149→
150→  private authenticate(req: http.IncomingMessage): boolean {
151→    const authHeader = req.headers.authorization
152→    if (!authHeader?.startsWith('Bearer ')) return false
153→    const token = authHeader.slice(7)
154→    if (token.length !== this.secret.length) return false
155→    return crypto.timingSafeEqual(Buffer.from(token, 'utf-8'), Buffer.from(this.secret, 'utf-8'))
156→  }
157→
158→  private async handleRequest(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
159→    const method = req.method?.toUpperCase()
160→    const url = req.url || ''
161→
162→    const isExempt = (method === 'GET' && (url === '/api/health' || url === '/api/version'))
163→    if (!isExempt && !this.authenticate(req)) {
164→      this.sendJson(res, 401, { error: 'Unauthorized' })
165→      return
166→    }
167→
168→    try {
169→      if (method === 'POST' && url === '/api/sessions/adopt') {
170→        await this.handleAdoptSession(req, res)
171→      } else if (method === 'POST' && url === '/api/sessions') {
172→        await this.handleCreateSession(req, res)
173→      } else if (method === 'POST' && url.match(/^\/api\/sessions\/([^/]+)\/prompt$/)) {
174→        const sessionId = decodeURIComponent(url.match(/^\/api\/sessions\/([^/]+)\/prompt$/)![1])
175→        await this.handleSendPrompt(sessionId, req, res)
176→      } else if (method === 'PATCH' && url.match(/^\/api\/sessions\/([^/]+)\/dangerous$/)) {
177→        const sessionId = decodeURIComponent(url.match(/^\/api\/sessions\/([^/]+)\/dangerous$/)![1])
178→        await this.handleToggleDangerous(sessionId, req, res)
179→      } else if (method === 'GET' && url.match(/^\/api\/sessions\/([^/]+)$/)) {
180→        const sessionId = decodeURIComponent(url.match(/^\/api\/sessions\/([^/]+)$/)![1])
181→        await this.handleGetSession(sessionId, res)
182→      } else if (method === 'DELETE' && url.match(/^\/api\/sessions\/([^/]+)$/)) {
183→        const sessionId = decodeURIComponent(url.match(/^\/api\/sessions\/([^/]+)$/)![1])
184→        await this.handleCancelSession(sessionId, res)
185→      } else if (method === 'GET' && url === '/api/sessions') {
186→        await this.handleListSessions(res)
187→      } else if (method === 'GET' && url === '/api/agents') {
188→        await this.handleListAgents(res)
189→      } else if (method === 'GET' && url === '/api/health') {
190→        await this.handleHealth(res)
191→      } else if (method === 'GET' && url === '/api/version') {
192→        await this.handleVersion(res)
193→      } else if (method === 'GET' && url === '/api/config/editable') {
194→        await this.handleGetEditableConfig(res)
195→      } else if (method === 'GET' && url === '/api/config') {
196→        await this.handleGetConfig(res)
197→      } else if (method === 'PATCH' && url === '/api/config') {
198→        await this.handleUpdateConfig(req, res)
199→      } else if (method === 'GET' && url === '/api/adapters') {
200→        await this.handleListAdapters(res)
201→      } else if (method === 'GET' && url === '/api/tunnel') {
202→        await this.handleTunnelStatus(res)
203→      } else if (method === 'POST' && url === '/api/notify') {
204→        await this.handleNotify(req, res)
205→      } else if (method === 'POST' && url === '/api/restart') {
206→        await this.handleRestart(res)
207→      } else if (method === 'GET' && url.match(/^\/api\/topics(\?.*)?$/)) {
208→        await this.handleListTopics(url, res)
209→      } else if (method === 'POST' && url === '/api/topics/cleanup') {
210→        await this.handleCleanupTopics(req, res)
211→      } else if (method === 'DELETE' && url.match(/^\/api\/topics\/([^/?]+)/)) {
212→        const match = url.match(/^\/api\/topics\/([^/?]+)/)!
213→        await this.handleDeleteTopic(decodeURIComponent(match[1]), url, res)
214→      } else {
215→        this.sendJson(res, 404, { error: 'Not found' })
216→      }
217→    } catch (err) {
218→      log.error({ err }, 'API request error')
219→      this.sendJson(res, 500, { error: 'Internal server error' })
220→    }
221→  }
