223→  private async handleCreateSession(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
224→    const body = await this.readBody(req)
225→    let agent: string | undefined
226→    let workspace: string | undefined
227→
228→    if (body) {
229→      try {
230→        const parsed = JSON.parse(body)
231→        agent = parsed.agent
232→        workspace = parsed.workspace
233→      } catch {
234→        this.sendJson(res, 400, { error: 'Invalid JSON body' })
235→        return
236→      }
237→    }
238→
239→    // Check max concurrent sessions
240→    const config = this.core.configManager.get()
241→    const activeSessions = this.core.sessionManager.listSessions()
242→      .filter(s => s.status === 'active' || s.status === 'initializing')
243→    if (activeSessions.length >= config.security.maxConcurrentSessions) {
244→      this.sendJson(res, 429, {
245→        error: `Max concurrent sessions (${config.security.maxConcurrentSessions}) reached. Cancel a session first.`,
246→      })
247→      return
248→    }
249→
250→    // Use the first registered adapter (e.g. Telegram) so API sessions appear in the channel
251→    const [adapterId, adapter] = this.core.adapters.entries().next().value ?? [null, null]
252→    const channelId = adapterId ?? 'api'
253→
254→    const resolvedAgent = agent || config.defaultAgent
255→    const resolvedWorkspace = this.core.configManager.resolveWorkspace(
256→      workspace || config.agents[resolvedAgent]?.workingDirectory,
257→    )
258→
259→    const session = await this.core.createSession({
260→      channelId,
261→      agentName: resolvedAgent,
262→      workingDirectory: resolvedWorkspace,
263→      createThread: !!adapter,
264→      initialName: `🔄 ${resolvedAgent} — New Session`,
265→    })
266→
267→    // If no adapter wired events (headless), auto-approve permissions
268→    if (!adapter) {
269→      session.agentInstance.onPermissionRequest = async (request) => {
270→        const allowOption = request.options.find(o => o.isAllow)
271→        log.debug({ sessionId: session.id, permissionId: request.id, option: allowOption?.id }, 'Auto-approving permission for API session')
272→        return allowOption?.id ?? request.options[0]?.id ?? ''
273→      }
274→    }
275→
276→    // Warmup in background so session moves from 'initializing' to 'active'
277→    session.warmup().catch(err => log.warn({ err, sessionId: session.id }, 'API session warmup failed'))
278→
279→    this.sendJson(res, 200, {
280→      sessionId: session.id,
281→      agent: session.agentName,
282→      status: session.status,
283→      workspace: session.workingDirectory,
284→    })
285→  }
