287→  private async handleSendPrompt(sessionId: string, req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
288→    const session = this.core.sessionManager.getSession(sessionId)
289→    if (!session) {
290→      this.sendJson(res, 404, { error: `Session "${sessionId}" not found` })
291→      return
292→    }
293→
294→    if (session.status === 'cancelled' || session.status === 'finished' || session.status === 'error') {
295→      this.sendJson(res, 400, { error: `Session is ${session.status}` })
296→      return
297→    }
298→
299→    const body = await this.readBody(req)
300→    let prompt: string | undefined
301→    if (body) {
302→      try {
303→        const parsed = JSON.parse(body)
304→        prompt = parsed.prompt
305→      } catch {
306→        this.sendJson(res, 400, { error: 'Invalid JSON body' })
307→        return
308→      }
309→    }
310→
311→    if (!prompt) {
312→      this.sendJson(res, 400, { error: 'Missing prompt' })
313→      return
314→    }
315→
316→    session.enqueuePrompt(prompt).catch(() => {})
317→    this.sendJson(res, 200, { ok: true, sessionId, queueDepth: session.queueDepth })
318→  }
