320→  private async handleGetSession(sessionId: string, res: http.ServerResponse): Promise<void> {
321→    const session = this.core.sessionManager.getSession(sessionId)
322→    if (!session) {
323→      this.sendJson(res, 404, { error: `Session "${sessionId}" not found` })
324→      return
325→    }
326→
327→    this.sendJson(res, 200, {
328→      session: {
329→        id: session.id,
330→        agent: session.agentName,
331→        status: session.status,
332→        name: session.name ?? null,
333→        workspace: session.workingDirectory,
334→        createdAt: session.createdAt.toISOString(),
335→        dangerousMode: session.dangerousMode,
336→        queueDepth: session.queueDepth,
337→        promptRunning: session.promptRunning,
338→        threadId: session.threadId,
339→        channelId: session.channelId,
340→        agentSessionId: session.agentSessionId,
341→      },
342→    })
343→  }
