345→  private async handleToggleDangerous(sessionId: string, req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
346→    const session = this.core.sessionManager.getSession(sessionId)
347→    if (!session) {
348→      this.sendJson(res, 404, { error: `Session "${sessionId}" not found` })
349→      return
350→    }
351→
352→    const body = await this.readBody(req)
353→    let enabled: boolean | undefined
354→    if (body) {
355→      try {
356→        const parsed = JSON.parse(body)
357→        enabled = parsed.enabled
358→      } catch {
359→        this.sendJson(res, 400, { error: 'Invalid JSON body' })
360→        return
361→      }
362→    }
363→
364→    if (typeof enabled !== 'boolean') {
365→      this.sendJson(res, 400, { error: 'Missing enabled boolean' })
366→      return
367→    }
368→
369→    session.dangerousMode = enabled
370→    await this.core.sessionManager.patchRecord(sessionId, { dangerousMode: enabled })
371→    this.sendJson(res, 200, { ok: true, dangerousMode: enabled })
372→  }
