374→  private async handleHealth(res: http.ServerResponse): Promise<void> {
375→    const activeSessions = this.core.sessionManager.listSessions()
376→    const allRecords = this.core.sessionManager.listRecords()
377→    const mem = process.memoryUsage()
378→    const tunnel = this.core.tunnelService
379→
380→    this.sendJson(res, 200, {
381→      status: 'ok',
382→      uptime: Date.now() - this.startedAt,
383→      version: getVersion(),
384→      memory: {
385→        rss: mem.rss,
386→        heapUsed: mem.heapUsed,
387→        heapTotal: mem.heapTotal,
388→      },
389→      sessions: {
390→        active: activeSessions.filter(s => s.status === 'active' || s.status === 'initializing').length,
391→        total: allRecords.length,
392→      },
393→      adapters: Array.from(this.core.adapters.keys()),
394→      tunnel: tunnel ? { enabled: true, url: tunnel.getPublicUrl() } : { enabled: false },
395→    })
396→  }
