402→  private async handleGetEditableConfig(res: http.ServerResponse): Promise<void> {
403→    const { getSafeFields, resolveOptions, getConfigValue } = await import('./config-registry.js')
404→    const config = this.core.configManager.get()
405→    const safeFields = getSafeFields()
406→
407→    const fields = safeFields.map((def) => ({
408→      path: def.path,
409→      displayName: def.displayName,
410→      group: def.group,
411→      type: def.type,
412→      options: resolveOptions(def, config),
413→      value: getConfigValue(config, def.path),
414→      hotReload: def.hotReload,
415→    }))
416→
417→    this.sendJson(res, 200, { fields })
418→  }
