425→  private async handleUpdateConfig(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
426→    const body = await this.readBody(req)
427→    let configPath: string | undefined
428→    let value: unknown
429→
430→    if (body) {
431→      try {
432→        const parsed = JSON.parse(body)
433→        configPath = parsed.path
434→        value = parsed.value
435→      } catch {
436→        this.sendJson(res, 400, { error: 'Invalid JSON body' })
437→        return
438→      }
439→    }
440→
441→    if (!configPath) {
442→      this.sendJson(res, 400, { error: 'Missing path' })
443→      return
444→    }
445→
446→    // Pre-validate by cloning config and applying the change
447→    const currentConfig = this.core.configManager.get()
448→    const cloned = structuredClone(currentConfig) as Record<string, unknown>
449→    const parts = configPath.split('.')
450→    let target: Record<string, unknown> = cloned
451→    for (let i = 0; i < parts.length - 1; i++) {
452→      if (target[parts[i]] && typeof target[parts[i]] === 'object' && !Array.isArray(target[parts[i]])) {
453→        target = target[parts[i]] as Record<string, unknown>
454→      } else {
455→        this.sendJson(res, 400, { error: 'Invalid config path' })
456→        return
457→      }
458→    }
459→
460→    const lastKey = parts[parts.length - 1]
461→    if (!(lastKey in target)) {
462→      this.sendJson(res, 400, { error: 'Invalid config path' })
463→      return
464→    }
465→
466→    target[lastKey] = value
467→
468→    // Validate with Zod
469→    const { ConfigSchema } = await import('./config.js')
470→    const result = ConfigSchema.safeParse(cloned)
471→    if (!result.success) {
472→      this.sendJson(res, 400, {
473→        error: 'Validation failed',
474→        details: result.error.issues.map(i => ({ path: i.path.join('.'), message: i.message })),
475→      })
476→      return
477→    }
478→
479→    // Convert dot-path to nested object for save
480→    const updates: Record<string, unknown> = {}
481→    let updateTarget = updates
482→    for (let i = 0; i < parts.length - 1; i++) {
483→      updateTarget[parts[i]] = {}
484→      updateTarget = updateTarget[parts[i]] as Record<string, unknown>
485→    }
486→    updateTarget[lastKey] = value
487→
488→    await this.core.configManager.save(updates, configPath)
489→
490→    const { isHotReloadable } = await import('./config-registry.js')
491→    const needsRestart = !isHotReloadable(configPath!)
492→
493→    this.sendJson(res, 200, {
494→      ok: true,
495→      needsRestart,
496→      config: redactConfig(this.core.configManager.get()),
497→    })
498→  }
