500→  private async handleListAdapters(res: http.ServerResponse): Promise<void> {
501→    const adapters = Array.from(this.core.adapters.entries()).map(([name]) => ({
502→      name,
503→      type: 'built-in' as const,
504→    }))
505→    this.sendJson(res, 200, { adapters })
506→  }
