508→  private async handleTunnelStatus(res: http.ServerResponse): Promise<void> {
509→    const tunnel = this.core.tunnelService
510→    if (tunnel) {
511→      this.sendJson(res, 200, { enabled: true, url: tunnel.getPublicUrl(), provider: this.core.configManager.get().tunnel.provider })
512→    } else {
513→      this.sendJson(res, 200, { enabled: false })
514→    }
515→  }
