517→  private async handleNotify(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
518→    const body = await this.readBody(req)
519→    let message: string | undefined
520→    if (body) {
521→      try {
522→        const parsed = JSON.parse(body)
523→        message = parsed.message
524→      } catch {
525→        this.sendJson(res, 400, { error: 'Invalid JSON body' })
526→        return
527→      }
528→    }
529→
530→    if (!message) {
531→      this.sendJson(res, 400, { error: 'Missing message' })
532→      return
533→    }
534→
535→    await this.core.notificationManager.notifyAll({
536→      sessionId: 'system',
537→      type: 'completed',
538→      summary: message,
539→    })
540→    this.sendJson(res, 200, { ok: true })
541→  }
