543→  private async handleRestart(res: http.ServerResponse): Promise<void> {
544→    if (!this.core.requestRestart) {
545→      this.sendJson(res, 501, { error: 'Restart not available' })
546→      return
547→    }
548→
549→    this.sendJson(res, 200, { ok: true, message: 'Restarting...' })
550→    setImmediate(() => this.core.requestRestart!())
551→  }
