553→  private async handleCancelSession(sessionId: string, res: http.ServerResponse): Promise<void> {
554→    const session = this.core.sessionManager.getSession(sessionId)
555→    if (!session) {
556→      this.sendJson(res, 404, { error: `Session "${sessionId}" not found` })
557→      return
558→    }
559→    await session.abortPrompt()
560→    this.sendJson(res, 200, { ok: true })
561→  }
