563→  private async handleListSessions(res: http.ServerResponse): Promise<void> {
564→    const sessions = this.core.sessionManager.listSessions()
565→    this.sendJson(res, 200, {
566→      sessions: sessions.map(s => ({
567→        id: s.id,
568→        agent: s.agentName,
569→        status: s.status,
570→        name: s.name ?? null,
571→        workspace: s.workingDirectory,
572→      })),
573→    })
574→  }
