576→  private async handleAdoptSession(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
577→    const body = await this.readBody(req)
578→    if (!body) {
579→      return this.sendJson(res, 400, { error: 'bad_request', message: 'Empty request body' })
580→    }
581→
582→    let parsed: { agent?: string; agentSessionId?: string; cwd?: string }
583→    try {
584→      parsed = JSON.parse(body)
585→    } catch {
586→      return this.sendJson(res, 400, { error: 'bad_request', message: 'Invalid JSON' })
587→    }
588→
589→    const { agent, agentSessionId, cwd } = parsed
590→
591→    if (!agent || !agentSessionId) {
592→      return this.sendJson(res, 400, { error: 'bad_request', message: 'Missing required fields: agent, agentSessionId' })
593→    }
594→
595→    const result = await this.core.adoptSession(agent, agentSessionId, cwd ?? process.cwd())
596→
597→    if (result.ok) {
598→      return this.sendJson(res, 200, result)
599→    } else {
600→      const status = result.error === 'session_limit' ? 429 : result.error === 'agent_not_supported' ? 400 : 500
601→      return this.sendJson(res, status, result)
602→    }
603→  }
604→
605→  private async handleListAgents(res: http.ServerResponse): Promise<void> {
606→    const agents = this.core.agentManager.getAvailableAgents()
607→    const defaultAgent = this.core.configManager.get().defaultAgent
608→    const agentsWithCaps = agents.map((a) => ({
609→      ...a,
610→      capabilities: getAgentCapabilities(a.name),
611→    }))
612→    this.sendJson(res, 200, { agents: agentsWithCaps, default: defaultAgent })
613→  }
614→
615→  private sendJson(res: http.ServerResponse, status: number, data: unknown): void {
616→    res.writeHead(status, { 'Content-Type': 'application/json' })
617→    res.end(JSON.stringify(data))
618→  }
619→
620→  private async handleListTopics(url: string, res: http.ServerResponse): Promise<void> {
621→    if (!this.topicManager) { this.sendJson(res, 501, { error: 'Topic management not available' }); return }
622→    const params = new URL(url, 'http://localhost').searchParams
623→    const statusParam = params.get('status')
624→    const filter = statusParam ? { statuses: statusParam.split(',') } : undefined
625→    const topics = this.topicManager.listTopics(filter)
626→    this.sendJson(res, 200, { topics })
627→  }
628→
629→  private async handleDeleteTopic(sessionId: string, url: string, res: http.ServerResponse): Promise<void> {
630→    if (!this.topicManager) { this.sendJson(res, 501, { error: 'Topic management not available' }); return }
631→    const params = new URL(url, 'http://localhost').searchParams
632→    const force = params.get('force') === 'true'
633→    const result = await this.topicManager.deleteTopic(sessionId, force ? { confirmed: true } : undefined)
634→    if (result.ok) {
635→      this.sendJson(res, 200, result)
636→    } else if (result.needsConfirmation) {
637→      this.sendJson(res, 409, { error: 'Session is active', needsConfirmation: true, session: result.session })
638→    } else if (result.error === 'Cannot delete system topic') {
639→      this.sendJson(res, 403, { error: result.error })
640→    } else {
641→      this.sendJson(res, 404, { error: result.error ?? 'Not found' })
642→    }
643→  }
644→
645→  private async handleCleanupTopics(req: http.IncomingMessage, res: http.ServerResponse): Promise<void> {
646→    if (!this.topicManager) { this.sendJson(res, 501, { error: 'Topic management not available' }); return }
647→    const body = await this.readBody(req)
648→    let statuses: string[] | undefined
649→    if (body) {
650→      try { statuses = JSON.parse(body).statuses } catch { /* use defaults */ }
651→    }
652→    const result = await this.topicManager.cleanup(statuses)
653→    this.sendJson(res, 200, result)
654→  }
655→
656→  private readBody(req: http.IncomingMessage): Promise<string> {
657→    return new Promise((resolve) => {
658→      let data = ''
659→      req.on('data', (chunk) => { data += chunk })
660→      req.on('end', () => resolve(data))
661→      req.on('error', () => resolve(''))
662→    })
663→  }
664→}
