  1→import { spawn } from 'node:child_process'
  2→import * as fs from 'node:fs'
  3→import * as path from 'node:path'
  4→import * as os from 'node:os'
  5→import { expandHome } from './config.js'
  6→
  7→const DEFAULT_PID_PATH = path.join(os.homedir(), '.openacp', 'openacp.pid')
  8→const DEFAULT_LOG_DIR = path.join(os.homedir(), '.openacp', 'logs')
  9→const RUNNING_MARKER = path.join(os.homedir(), '.openacp', 'running')
 10→
 11→export function writePidFile(pidPath: string, pid: number): void {
 12→  const dir = path.dirname(pidPath)
 13→  fs.mkdirSync(dir, { recursive: true })
 14→  fs.writeFileSync(pidPath, String(pid))
 15→}
 16→
 17→export function readPidFile(pidPath: string): number | null {
 18→  try {
 19→    const content = fs.readFileSync(pidPath, 'utf-8').trim()
 20→    const pid = parseInt(content, 10)
 21→    return isNaN(pid) ? null : pid
 22→  } catch {
 23→    return null
 24→  }
 25→}
 26→
 27→export function removePidFile(pidPath: string): void {
 28→  try {
 29→    fs.unlinkSync(pidPath)
 30→  } catch {
 31→    // ignore if already gone
 32→  }
 33→}
 34→
 35→export function isProcessRunning(pidPath: string): boolean {
 36→  const pid = readPidFile(pidPath)
 37→  if (pid === null) return false
 38→  try {
 39→    process.kill(pid, 0)
 40→    return true
 41→  } catch {
 42→    // Process not running, clean up stale PID file
 43→    removePidFile(pidPath)
 44→    return false
 45→  }
 46→}
 47→
 48→export function getStatus(pidPath: string = DEFAULT_PID_PATH): { running: boolean; pid?: number } {
 49→  const pid = readPidFile(pidPath)
 50→  if (pid === null) return { running: false }
 51→  try {
 52→    process.kill(pid, 0)
 53→    return { running: true, pid }
 54→  } catch {
 55→    removePidFile(pidPath)
 56→    return { running: false }
 57→  }
 58→}
 59→
 60→export function startDaemon(pidPath: string = DEFAULT_PID_PATH, logDir?: string): { pid: number } | { error: string } {
 61→  // Mark as running so auto-start works on next boot
 62→  markRunning()
 63→
 64→  // Check if already running
 65→  if (isProcessRunning(pidPath)) {
 66→    const pid = readPidFile(pidPath)!
 67→    return { error: `Already running (PID ${pid})` }
 68→  }
 69→
 70→  const resolvedLogDir = logDir ? expandHome(logDir) : DEFAULT_LOG_DIR
 71→  fs.mkdirSync(resolvedLogDir, { recursive: true })
 72→  const logFile = path.join(resolvedLogDir, 'openacp.log')
 73→
 74→  // Find the CLI entry point
 75→  const cliPath = path.resolve(process.argv[1])
 76→  const nodePath = process.execPath
 77→
 78→  const out = fs.openSync(logFile, 'a')
 79→  const err = fs.openSync(logFile, 'a')
 80→
 81→  const child = spawn(nodePath, [cliPath, '--daemon-child'], {
 82→    detached: true,
 83→    stdio: ['ignore', out, err],
 84→  })
 85→
 86→  // Close file descriptors in parent — child has its own copies
 87→  fs.closeSync(out)
 88→  fs.closeSync(err)
 89→
 90→  if (!child.pid) {
 91→    return { error: 'Failed to spawn daemon process' }
 92→  }
 93→
 94→  // PID file is written by the child process itself (in main.ts startServer)
 95→  // to avoid race conditions and ensure consistency with LaunchAgent/systemd starts.
 96→  // We still write it here as a fallback in case the child hasn't written it yet
 97→  // when the parent needs to report the PID.
 98→  writePidFile(pidPath, child.pid)
 99→  child.unref()
100→
101→  return { pid: child.pid }
102→}
103→
104→function sleep(ms: number): Promise<void> {
105→  return new Promise(resolve => setTimeout(resolve, ms))
106→}
107→
108→function isProcessAlive(pid: number): 'alive' | 'dead' | 'eperm' {
109→  try {
110→    process.kill(pid, 0)
111→    return 'alive'
112→  } catch (e) {
113→    const err = e as NodeJS.ErrnoException
114→    if (err.code === 'EPERM') return 'eperm'
115→    return 'dead'
116→  }
117→}
118→
119→export async function stopDaemon(pidPath: string = DEFAULT_PID_PATH): Promise<{ stopped: boolean; pid?: number; error?: string }> {
120→  const pid = readPidFile(pidPath)
121→  if (pid === null) return { stopped: false, error: 'Not running (no PID file)' }
122→
123→  const status = isProcessAlive(pid)
124→  if (status === 'dead') {
125→    removePidFile(pidPath)
126→    return { stopped: false, error: 'Not running (stale PID file removed)' }
127→  }
128→  if (status === 'eperm') {
129→    removePidFile(pidPath)
130→    return { stopped: false, error: 'PID belongs to another process (stale PID file removed)' }
131→  }
132→
133→  try {
134→    process.kill(pid, 'SIGTERM')
135→  } catch (e) {
136→    return { stopped: false, error: `Failed to stop: ${(e as Error).message}` }
137→  }
138→
139→  clearRunning()
140→
141→  const POLL_INTERVAL = 100
142→  const TIMEOUT = 5000
143→  const start = Date.now()
144→
145→  while (Date.now() - start < TIMEOUT) {
146→    await sleep(POLL_INTERVAL)
147→    const s = isProcessAlive(pid)
148→    if (s === 'dead' || s === 'eperm') {
149→      removePidFile(pidPath)
150→      return { stopped: true, pid }
151→    }
152→  }
153→
154→  try {
155→    process.kill(pid, 'SIGKILL')
156→  } catch (e) {
157→    const err = e as NodeJS.ErrnoException
158→    if (err.code === 'EPERM') {
159→      return { stopped: false, pid, error: 'PID may have been reused by another process. Run `openacp status` to verify, or manually delete the PID file.' }
160→    }
161→  }
162→
163→  const killStart = Date.now()
164→  while (Date.now() - killStart < 1000) {
165→    await sleep(POLL_INTERVAL)
166→    const s = isProcessAlive(pid)
167→    if (s === 'dead' || s === 'eperm') {
168→      removePidFile(pidPath)
169→      return { stopped: true, pid }
170→    }
171→  }
172→
173→  // SIGKILL sent but process still alive after 1s — extremely rare (uninterruptible I/O).
174→  return { stopped: false, pid, error: 'Process did not exit after SIGKILL (possible uninterruptible I/O). PID file retained.' }
175→}
176→
177→export function getPidPath(): string {
178→  return DEFAULT_PID_PATH
179→}
180→
181→/** Mark that the daemon should auto-start on boot */
182→export function markRunning(): void {
183→  fs.mkdirSync(path.dirname(RUNNING_MARKER), { recursive: true })
184→  fs.writeFileSync(RUNNING_MARKER, '')
185→}
186→
187→/** Remove running marker — daemon won't auto-start on boot */
188→export function clearRunning(): void {
189→  try { fs.unlinkSync(RUNNING_MARKER) } catch { /* ignore */ }
190→}
191→
192→/** Check if the daemon was running before (should auto-start on boot) */
193→export function shouldAutoStart(): boolean {
194→  return fs.existsSync(RUNNING_MARKER)
195→}
