144→export class ConfigManager extends EventEmitter {
145→  private config!: Config;
146→  private configPath: string;
147→
148→  constructor() {
149→    super();
150→    this.configPath =
151→      process.env.OPENACP_CONFIG_PATH || expandHome("~/.openacp/config.json");
152→  }
153→
154→  async load(): Promise<void> {
155→    // 1. Ensure directory exists
156→    const dir = path.dirname(this.configPath);
157→    fs.mkdirSync(dir, { recursive: true });
158→
159→    // 2. If config file doesn't exist, create default
160→    if (!fs.existsSync(this.configPath)) {
161→      fs.writeFileSync(
162→        this.configPath,
163→        JSON.stringify(DEFAULT_CONFIG, null, 2),
164→      );
165→      log.info({ configPath: this.configPath }, "Config created");
166→      log.info(
167→        "Please edit it with your channel credentials (Telegram bot token, Discord bot token, etc.), then restart.",
168→      );
169→      process.exit(1);
170→    }
171→
172→    // 3. Read and parse
173→    const raw = JSON.parse(fs.readFileSync(this.configPath, "utf-8"));
174→
175→    // 3.5. Auto-migrate config
176→    const { changed: configUpdated } = applyMigrations(raw);
177→    if (configUpdated) {
178→      fs.writeFileSync(this.configPath, JSON.stringify(raw, null, 2));
179→    }
180→
181→    // 4. Apply env var overrides
182→    this.applyEnvOverrides(raw);
183→
184→    // 5. Validate with Zod
185→    const result = ConfigSchema.safeParse(raw);
186→    if (!result.success) {
187→      log.error("Config validation failed");
188→      for (const issue of result.error.issues) {
189→        log.error(
190→          { path: issue.path.join("."), message: issue.message },
191→          "Validation error",
192→        );
193→      }
194→      process.exit(1);
195→    }
196→    this.config = result.data;
197→  }
198→
199→  get(): Config {
200→    return this.config;
201→  }
202→
203→  async save(updates: Record<string, unknown>, changePath?: string): Promise<void> {
204→    const oldConfig = this.config ? structuredClone(this.config) : undefined;
205→    // Read current file, merge updates, write back
206→    const raw = JSON.parse(fs.readFileSync(this.configPath, "utf-8"));
207→    this.deepMerge(raw, updates);
208→    fs.writeFileSync(this.configPath, JSON.stringify(raw, null, 2));
209→    // Re-validate and update in-memory config
210→    const result = ConfigSchema.safeParse(raw);
211→    if (result.success) {
212→      this.config = result.data;
213→    }
214→    // Emit change event if path provided
215→    if (changePath) {
216→      const { getConfigValue } = await import('./config-registry.js')
217→      const value = getConfigValue(this.config, changePath)
218→      const oldValue = oldConfig ? getConfigValue(oldConfig, changePath) : undefined
219→      this.emit('config:changed', { path: changePath, value, oldValue })
220→    }
221→  }
222→
223→  resolveWorkspace(input?: string): string {
224→    if (!input) {
225→      const resolved = expandHome(this.config.workspace.baseDir);
226→      fs.mkdirSync(resolved, { recursive: true });
227→      return resolved;
228→    }
229→    if (input.startsWith("/") || input.startsWith("~")) {
230→      const resolved = expandHome(input);
231→      fs.mkdirSync(resolved, { recursive: true });
232→      return resolved;
233→    }
234→    // Named workspace → lowercase, under baseDir
235→    const name = input.toLowerCase();
236→    const resolved = path.join(expandHome(this.config.workspace.baseDir), name);
237→    fs.mkdirSync(resolved, { recursive: true });
238→    return resolved;
239→  }
240→
241→  async exists(): Promise<boolean> {
242→    return fs.existsSync(this.configPath);
243→  }
244→
245→  getConfigPath(): string {
246→    return this.configPath;
247→  }
248→
249→  async writeNew(config: Config): Promise<void> {
250→    const dir = path.dirname(this.configPath);
251→    fs.mkdirSync(dir, { recursive: true });
252→    fs.writeFileSync(this.configPath, JSON.stringify(config, null, 2));
253→  }
254→
255→  private applyEnvOverrides(raw: Record<string, unknown>): void {
256→    const overrides: [string, string[]][] = [
257→      ["OPENACP_TELEGRAM_BOT_TOKEN", ["channels", "telegram", "botToken"]],
258→      ["OPENACP_TELEGRAM_CHAT_ID", ["channels", "telegram", "chatId"]],
259→      ["OPENACP_DISCORD_BOT_TOKEN", ["channels", "discord", "botToken"]],
260→      ["OPENACP_DISCORD_GUILD_ID", ["channels", "discord", "guildId"]],
261→      ["OPENACP_DEFAULT_AGENT", ["defaultAgent"]],
262→      ["OPENACP_RUN_MODE", ["runMode"]],
263→      ["OPENACP_API_PORT", ["api", "port"]],
264→    ];
265→    for (const [envVar, configPath] of overrides) {
266→      const value = process.env[envVar];
267→      if (value !== undefined) {
268→        let target = raw as Record<string, any>;
269→        for (let i = 0; i < configPath.length - 1; i++) {
270→          if (!target[configPath[i]]) target[configPath[i]] = {};
271→          target = target[configPath[i]];
272→        }
273→        const key = configPath[configPath.length - 1];
274→        // Convert numeric fields to number
275→        target[key] = (key === "chatId" || key === "port") ? Number(value) : value;
276→      }
277→    }
278→
279→    // Logging env var overrides
280→    if (process.env.OPENACP_LOG_LEVEL) {
281→      raw.logging = raw.logging || {};
282→      (raw.logging as Record<string, unknown>).level =
283→        process.env.OPENACP_LOG_LEVEL;
284→    }
285→    if (process.env.OPENACP_LOG_DIR) {
286→      raw.logging = raw.logging || {};
287→      (raw.logging as Record<string, unknown>).logDir =
288→        process.env.OPENACP_LOG_DIR;
289→    }
290→    if (process.env.OPENACP_DEBUG && !process.env.OPENACP_LOG_LEVEL) {
291→      raw.logging = raw.logging || {};
292→      (raw.logging as Record<string, unknown>).level = "debug";
293→    }
294→
295→    // Tunnel env var overrides
296→    if (process.env.OPENACP_TUNNEL_ENABLED) {
297→      raw.tunnel = raw.tunnel || {};
298→      (raw.tunnel as Record<string, unknown>).enabled =
299→        process.env.OPENACP_TUNNEL_ENABLED === "true";
300→    }
301→    if (process.env.OPENACP_TUNNEL_PORT) {
302→      raw.tunnel = raw.tunnel || {};
303→      (raw.tunnel as Record<string, unknown>).port = Number(
304→        process.env.OPENACP_TUNNEL_PORT,
305→      );
306→    }
307→    if (process.env.OPENACP_TUNNEL_PROVIDER) {
308→      raw.tunnel = raw.tunnel || {};
309→      (raw.tunnel as Record<string, unknown>).provider =
310→        process.env.OPENACP_TUNNEL_PROVIDER;
311→    }
312→  }
313→
314→  private deepMerge(
315→    target: Record<string, any>,
316→    source: Record<string, any>,
317→  ): void {
318→    for (const key of Object.keys(source)) {
319→      if (
320→        source[key] &&
321→        typeof source[key] === "object" &&
322→        !Array.isArray(source[key])
323→      ) {
324→        if (!target[key]) target[key] = {};
325→        this.deepMerge(target[key], source[key]);
326→      } else {
327→        target[key] = source[key];
328→      }
329→    }
330→  }
331→}
